"""Version 2 resource presentation. Original workbook substance is retained in resources.json."""
import re

RESOURCE_META = {
    'healthcare-growth-diagnostic': dict(category='Growth', tone='sky', short='Healthcare growth', cover='From interest<br>to <em>arrival.</em>', description='Find the gaps between discovery, appointment and arrival.', start='One service. Four recent weeks.', outcome='A patient-journey baseline and one gap to investigate.', steps=['Discover','Book','Arrive'], summaries=['Record the starting numbers.','Follow the path to an appointment.','Check what the team can handle.','Choose one question to investigate.']),
    'manufacturing-digitisation-checklist': dict(category='Operations', tone='sage', short='Factory digitisation', cover='Make the<br>workflow <em>visible.</em>', description='Map a recurring factory process before choosing software.', start='One workflow and its approver.', outcome='A process map with rules, exceptions and a first scope.', steps=['Record','Review','Approve'], summaries=['Map the work as it happens.','Measure time, volume and corrections.','Identify where the usual flow breaks.','Define what the first version must do.']),
    'website-conversion-audit': dict(category='Websites', tone='peach', short='Website conversion', cover='Clear offer.<br><em>Clear next step.</em>', description='Check what visitors understand, trust and do on your website.', start='One page. One visitor. One action.', outcome='One evidence-based change to test on desktop and mobile.', steps=['Understand','Trust','Act'], summaries=['Choose who the page is for.','Check the offer and the proof.','Try the journey yourself.','Turn an observation into a test.']),
    'performance-tracking-checklist': dict(category='Growth', tone='butter', short='Campaign tracking', cover='Beyond<br>the <em>click.</em>', description='Connect campaign spend to enquiries and business outcomes.', start='One campaign and reporting period.', outcome='Agreed measures, owners and the gaps in your reporting.', steps=['Spend','Enquiry','Outcome'], summaries=['Decide what success actually means.','Test whether the events are recorded.','Follow enquiries into the sales process.','Check that the numbers reconcile.']),
    'real-estate-lead-leakage-guide': dict(category='Growth', tone='lilac', short='Property enquiries', cover='Enquiry to<br><em>site visit.</em>', description='See where property enquiries lose momentum before a visit.', start='One project and enquiry cohort.', outcome='One follow-up or handover gap to review with sales.', steps=['Enquire','Follow up','Visit'], summaries=['Choose a comparable group of enquiries.','Check who responds, and when.','Trace the next step through to a visit.','Agree one change with sales.']),
    'education-admissions-funnel': dict(category='Growth', tone='sky', short='Admissions journey', cover='Help them<br>choose <em>well.</em>', description='Review the path from programme discovery to enrolment.', start='One programme and intake.', outcome='A clearer view of applicant questions and admissions gaps.', steps=['Explore','Apply','Enrol'], summaries=['Record the numbers for this intake.','Understand what applicants need to know.','Review the steps toward enrolment.','Choose a relevant measure and change.']),
    'custom-software-requirements-workbook': dict(category='Operations', tone='sage', short='Software requirements', cover='Before<br>you <em>build.</em>', description='Turn a business process into a useful software brief.', start='One workflow, its users and sponsor.', outcome='A first-release brief with rules, dependencies and owners.', steps=['People','Rules','Release'], summaries=['Name the problem and its baseline.','Define roles, permissions and exceptions.','Check systems, data and constraints.','Agree essentials and acceptance examples.','Plan testing, support and review.']),
}

def clean_title(title):
    return re.sub(r'^\d+[.\s]+', '', title)

def resource_views(page, pagehero, link, resources, E, arrow):
    def route(r): return '/resources/'+r['slug']+'/'
    def diagram(meta):
        return '<div class="resource-diagram" aria-hidden="true">'+''.join(f'<div><span>{n+1:02}</span><b>{E(s)}</b></div>' for n,s in enumerate(meta['steps']))+'</div>'
    def card(r, featured=False):
        m=RESOURCE_META[r['slug']]; count=sum(len(s['questions']) for s in r['sections'])
        return f'''<a class="field-card tone-{m['tone']} {'field-featured' if featured else ''}" href="{route(r)}" data-resource-category="{m['category']}">
          <div class="field-cover"><div class="field-kicker"><span>{E(m['category'])}</span><span>Free workbook</span></div><div class="cover-title">{m['cover']}</div>{diagram(m)}</div>
          <div class="field-copy"><div class="field-meta">{len(r['sections'])} sections <span>·</span> {count} prompts</div><h2>{E(m['short'])}</h2><p>{E(m['description'])}</p><div class="card-open">Open workbook <span class="circle-arrow" aria-hidden="true">↗</span></div></div></a>'''
    content='''<section class="library-hero"><div class="wrap"><div class="breadcrumbs"><a href="/">Home</a> / <span>Resources</span></div><div class="library-intro"><div><div class="eyebrow">The Digiator workbooks</div><h1>A little clarity.<br>A <em>better next move.</em></h1><p class="lead">Practical tools to spot gaps, map a process<br class="desktop-break"> and brief the right work.</p><div class="library-benefits"><span>No sign-up</span><span>Yours to keep</span><span>Built to use</span></div></div><div class="clarity-note"><span class="note-label">HOW TO USE THESE</span><div class="note-symbol" aria-hidden="true">?</div><p>A few notes.<br><em>One next step.</em></p><ol><li>Pick a workbook.</li><li>Work through the prompts.</li><li>Save your next step.</li></ol></div></div></div></section>'''
    ordered=sorted(resources,key=lambda r:r['slug']!='website-conversion-audit')
    filters=''.join(f'<button type="button" data-resource-filter="{x}" aria-pressed="{"true" if x=="All" else "false"}">{x}</button>' for x in ['All','Growth','Websites','Operations'])
    content+=f'''<section class="section library-section"><div class="wrap"><div class="library-toolbar"><div><h2>What are you working on?</h2><p id="resource-count" aria-live="polite">7 workbooks. Choose the one that fits.</p></div><div class="resource-filters" role="group" aria-label="Filter workbooks">{filters}</div></div><div class="field-grid">{''.join(card(r,i==0) for i,r in enumerate(ordered))}</div><div class="library-footnote"><strong>Use what helps. Skip what doesn’t.</strong><p>These are working tools, not scores or certifications. Each helps you leave with a clearer question or brief.</p></div></div></section>'''
    page('resources','Free workbooks & guides','Seven practical tools for a clearer website, campaign, customer journey or software brief.',content,'resources')

    for r in resources:
        m=RESOURCE_META[r['slug']]; total=sum(len(s['questions']) for s in r['sections'])
        content=f'''<section class="workbook-hero tone-{m['tone']}"><div class="wrap"><div class="breadcrumbs"><a href="/">Home</a> / <a href="/resources/">Resources</a> / <span>{E(m['short'])}</span></div><div class="workbook-heading"><div><div class="eyebrow">Free workbook · {len(r['sections'])} sections</div><h1>{E(r['title'])}</h1><p class="lead">{E(m['description'])}</p></div><div class="workbook-mark" aria-hidden="true"><span>FIELD<br>NOTES</span><b>{resources.index(r)+1:02}</b></div></div><dl class="workbook-brief"><div><dt>For</dt><dd>{E(r['audience'])}</dd></div><div><dt>Start with</dt><dd>{E(m['start'])}</dd></div><div><dt>Leave with</dt><dd>{E(m['outcome'])}</dd></div></dl></div></section>'''
        instructions=r['instructions'] if isinstance(r['instructions'],str) else ' '.join(r['instructions'])
        navigation=''.join(f'<a href="#section-{n}" data-section-link="section-{n}"><span>{n+1:02}</span>{E(clean_title(s["title"]))}<i aria-hidden="true"></i></a>' for n,s in enumerate(r['sections']))
        sections=''
        for n,s in enumerate(r['sections']):
            questions=''
            for j,q in enumerate(s['questions']):
                split=q.find('?')+1 if '?' in q else q.find('.')+1
                prompt=q[:split] if split else q
                hint=q[split:].strip() if split else ''
                questions+=f'''<div class="workbook-question"><label for="q-{n}-{j}"><span>{E(prompt)}</span></label>{f'<p id="hint-{n}-{j}" class="question-hint">{E(hint)}</p>' if hint else ''}<textarea id="q-{n}-{j}" rows="2" placeholder="A few notes are enough…" autocomplete="off" {f'aria-describedby="hint-{n}-{j}"' if hint else ''}></textarea><div class="print-answer" aria-hidden="true"></div></div>'''
            next_button=f'<button class="btn dark" type="button" data-next-section="section-{n+1}">Next section <span aria-hidden="true">→</span></button>' if n<len(r['sections'])-1 else '<a class="btn dark" href="#keep-your-notes">Keep your notes <span aria-hidden="true">↓</span></a>'
            sections+=f'''<details class="workbook-section" id="section-{n}" {'open' if n==0 else ''}><summary><span class="section-index">{n+1:02}</span><div><h2>{E(clean_title(s['title']))}</h2><p>{E(m['summaries'][n])}</p></div><span class="step-toggle" aria-hidden="true">+</span></summary><div class="workbook-fields">{questions}<div class="step-bottom"><span>Notes are optional. “Unknown” is useful too.</span>{next_button}</div></div></details>'''
        content+=f'''<section class="section workbook-body"><div class="wrap workbook-layout"><aside class="workbook-rail"><div class="rail-inner"><span class="eyebrow">Your workbook</span><nav aria-label="Workbook sections">{navigation}</nav><div class="workbook-progress"><div><strong id="answered-count">0 of {total}</strong><span>prompts noted</span></div><progress max="{total}" value="0" aria-label="Prompts with notes"></progress></div><p>Notes stay in this tab.<br>Download before you leave.</p></div></aside><div class="workbook-main"><details class="before-start"><summary>Before you start <span aria-hidden="true">+</span></summary><p>{E(instructions)}</p><p>Use aggregate or fictional information. Leave out personal and confidential details.</p></details><p class="print-meta">Digiator · growth@digiator.com · +91 93431 17867</p>{sections}<section class="keep-notes" id="keep-your-notes"><div><span class="eyebrow">Make it useful</span><h2>Keep the notes.<br><em>Choose the next step.</em></h2><p>{E(r['nextStep'])}</p></div><div class="save-actions"><button class="btn dark" data-download-workbook="{r['slug']}">Download notes {arrow}</button><button class="btn light-outline" data-print>Print / save PDF</button><small>Your answers aren’t sent to Digiator.</small></div></section><p id="workbook-status" class="form-status" role="status"></p><div class="workbook-discuss"><span>A question worth exploring together?</span>{link('/consultation/','Talk it through with us')}</div></div></div></section>'''
        page('resources/'+r['slug'],r['title'],m['description'],content,'resources',include_cta=False)
